trace.message:
@{
    var requestContext=new JObject(new JProperty("requestId",context.RequestId.ToString()),
      new JProperty("apiId",context.Api==null ? null : context.Api.Id),
      new JProperty("operationId",context.Operation==null ? null : context.Operation.Id));
    if(context.Variables.ContainsKey("gatewayRequestContext")) {
      try {
        var snapshot=(string)context.Variables["gatewayRequestContext"];
        if(snapshot.Length <= 4096) {
          var stored=JObject.Parse(snapshot);
          foreach(var field in new [] { "requestReceivedAt","httpMethod","operationTemplate","apimPeerIp","reportedUserAgent","appGatewayTraceId" }) {
            var value=stored[field];
            if(field=="requestReceivedAt" && value?.Type==JTokenType.Date) { requestContext[field]=((DateTime)value).ToString("O"); }
            else if(field=="reportedUserAgent" && value?.Type==JTokenType.Date) {
              var text=Newtonsoft.Json.JsonConvert.DeserializeObject<System.Collections.Generic.Dictionary<string,string>>(snapshot)[field];
              requestContext[field]=text!=null && text.Length<=512 ? text : null;
            }
            else { requestContext[field]=value?.Type==JTokenType.String && ((string)value).Length <= 512 ? value : null; }
          }
        }
      } catch { }
    }
    __AUDIT_SUBJECT_OBSERVATION_CSHARP__
    var record=new JObject(new JProperty("schemaVersion",1),new JProperty("auditSchemaVersion",2),new JProperty("event","gateway-request"),
      new JProperty("requestId",requestContext["requestId"]),new JProperty("backendRequestId",requestContext["requestId"]),
      new JProperty("apiId",requestContext["apiId"]),new JProperty("operationId",requestContext["operationId"]),
      new JProperty("phase",(string)context.Variables["gatewayAuditPhase"]),
      new JProperty("code",(string)context.Variables["gatewayAuditCode"]),
      new JProperty("status",(int)context.Variables["gatewayAuditStatus"]),
      new JProperty("authorization","unconfirmed"),new JProperty("usageStatus","none"),new JProperty("usageSource","none"),
      new JProperty("requestContext",requestContext),new JProperty("authenticatedSubject",authenticatedSubject));
    try {
      var decision=JObject.Parse((string)context.Variables["gatewayDecision"]);
      var caller=(string)context.Variables["credentialCallerId"];
      var allowed=decision["allowed"]?.Type==JTokenType.Boolean && (bool)decision["allowed"];
      record["authorization"]=allowed ? "allowed" : "denied";
      if(allowed && (string)decision["callerId"]==caller) {
        if(context.Subscription!=null && (string)decision["method"]=="subscriptionKey" && caller=="subscription:"+context.Subscription.Id) {
          record["method"]="subscriptionKey"; record["callerId"]=caller; record["subscriptionId"]=context.Subscription.Id;
        } else if(context.Subscription==null && (string)decision["method"]=="user" && caller.StartsWith("user:")
            && (string)decision["allocationId"]==caller) {
          var user=JObject.Parse((string)context.Variables["gatewayUserAuthentication"]);
          record["method"]="user"; record["callerId"]=caller; record["allocationId"]=caller;
          record["verifiedTenantId"]=user["tenantId"]; record["verifiedPrincipalId"]=user["principalId"];
          record["verifiedClientId"]=(string)user["clientId"]??"";
        } else { record["authorization"]="unconfirmed"; }
        if(decision["profileId"]?.Type==JTokenType.String) { record["profileId"]=decision["profileId"]; }
      } else if(allowed) { record["authorization"]="unconfirmed"; }
      var settings=JObject.Parse((string)context.Variables["gatewayAuditSettings"]);
      foreach(var field in new [] { "backendService","backendAuthentication","measurementRole","serviceClass" }) { record[field]=settings[field]; }
      if(context.Variables.ContainsKey("gatewayAuditModel")) { record["targetModel"]=(string)context.Variables["gatewayAuditModel"]; }
    } catch { }
    return record.ToString(Newtonsoft.Json.Formatting.None);
  }
